"""RUM15 diagnostic: FP32 IQ8R scale products for native GEMM; not in serving-core.

This is a precision-preserving experiment, not a TP3 serving enablement.
The same Radiance libr4d source is rewritten by the libr3 component for gfx1100.
"""
from __future__ import annotations
import re
from bigcherry.patcher import Edit, FilePatch

def rep(ident: str, before: str, after: str) -> Edit:
    return Edit(id=ident, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(after), expect_matches=1,
                max_span_lines=max(4, before.count("\n")+2),
                rationale="RUM15: preserve IQ8R U8*BF16 scale in F32 through native GPU fold")

PATCHES = (
    FilePatch(path='libr4d/r4d_fp8_layout.cpp', language="none",
              description='RUM15 scale-layout F32 IQ8R scale', edits=(
        rep('rum15-scale-layout-1', '            return RAD_E_SHAPE;\n        }\n        if (g.N % r4d_fp8::kFragRows) return RAD_E_SHAPE;\n        ffill(out, wide ? "r4d.iq8r.s.t16" : "r4d.i8.s.t16", RAD_BF16, g.N, g.sk, g.N * g.sk * 2);\n        return RAD_OK;\n    }\n    if (!r4d_enc::selects(enc, sel, n, "codes") || !r4d_enc::dims(pl[0], g.N, g.K))\n', '            return RAD_E_SHAPE;\n        }\n        if (g.N % r4d_fp8::kFragRows) return RAD_E_SHAPE;\n        ffill(out, wide ? "r4d.iq8r.s.f32.t16" : "r4d.i8.s.t16",\n              wide ? RAD_F32 : RAD_BF16, g.N, g.sk, g.N * g.sk * (wide ? 4 : 2));\n        return RAD_OK;\n    }\n    if (!r4d_enc::selects(enc, sel, n, "codes") || !r4d_enc::dims(pl[0], g.N, g.K))\n'),
        rep('rum15-scale-layout-2', "    if (dst_bytes != L.bytes || !pl[0].data) return RAD_E_SHAPE;\n    if (operand == FL_BSCALE) {\n        const long long N = pl[0].shape[0], nkb = pl[0].shape[1];\n        uint16_t* d = (uint16_t*)dst;\n        if (n == 2) {\n            /* IQ8R: the two levels' product, the one bf16 the fold multiplies by. */\n            if (!pl[1].data) return RAD_E_SHAPE;\n            for (long long r = 0; r < N; ++r) {\n                const uint8_t* s1 = r4d_enc::row(pl[0], r);\n                const float s2 = rad_load_f32(pl[1].data, RAD_BF16, r);\n                for (long long kb = 0; kb < nkb; ++kb)\n                    rad_store_f32(d, RAD_BF16, ((r / 16) * nkb + kb) * 16 + r % 16,\n                                  (float)s1[kb] * s2);\n            }\n            return RAD_OK;\n        }\n        const uint16_t* s = (const uint16_t*)pl[0].data;\n        for (long long r = 0; r < N; ++r)\n            for (long long kb = 0; kb < nkb; ++kb)\n", "    if (dst_bytes != L.bytes || !pl[0].data) return RAD_E_SHAPE;\n    if (operand == FL_BSCALE) {\n        const long long N = pl[0].shape[0], nkb = pl[0].shape[1];\n        if (n == 2) {\n            // Preserve the exactly representable product of the 8-bit\n            // coefficient and BF16 row gain through GEMM's F32 fold.\n            if (!pl[1].data) return RAD_E_SHAPE;\n            float* d = (float*)dst;\n            for (long long r = 0; r < N; ++r) {\n                const uint8_t* s1 = r4d_enc::row(pl[0], r);\n                const float s2 = rad_load_f32(pl[1].data, RAD_BF16, r);\n                for (long long kb = 0; kb < nkb; ++kb)\n                    d[((r / 16) * nkb + kb) * 16 + r % 16] = (float)s1[kb] * s2;\n            }\n            return RAD_OK;\n        }\n        uint16_t* d = (uint16_t*)dst;\n        const uint16_t* s = (const uint16_t*)pl[0].data;\n        for (long long r = 0; r < N; ++r)\n            for (long long kb = 0; kb < nkb; ++kb)\n"),
    )),
    FilePatch(path='libr4d/r4d_gemm_i8a8.hip', language="none",
              description="RUM15 IQ8R F32 scale reads", edits=(
        rep('rum15-decode-kpar-narrow-1', '    constexpr uint32_t kWS = MW * kFolds * 8u;\n', '    // One dword per wide IQ8R scale, two BF16 values per dword otherwise.\n    constexpr uint32_t kScaleWords_rad0061 = SB == 256u ? 16u : 8u;\n    constexpr uint32_t kWS = MW * kFolds * kScaleWords_rad0061;\n'),
        rep('rum15-decode-kpar-narrow-2', '        const uint32_t tr = (m0 + (i / (kFolds * 8u)) * 16u) / 16u;\n        const uint32_t kb = c / SB + (i / 8u) % kFolds;\n        return ((Full || tr * 16u < rows) && kb < nkb8)\n            ? ((const uint32_t*)Sa)[((size_t)tr * nkb8 + kb) * 8u + i % 8u] : 0u;\n', '        const uint32_t tr = (m0 + (i / (kFolds * kScaleWords_rad0061)) * 16u) / 16u;\n        const uint32_t kb = c / SB + (i / kScaleWords_rad0061) % kFolds;\n        return ((Full || tr * 16u < rows) && kb < nkb8)\n            ? ((const uint32_t*)Sa)[((size_t)tr * nkb8 + kb) * kScaleWords_rad0061 + i % kScaleWords_rad0061] : 0u;\n'),
        rep('rum15-decode-kpar-narrow-3', '                float wsr[8];\n                {\n                    const uint4 w8 =\n                        *(const uint4*)&s_ws[(wave * kFolds + f) * 8u + (lane >> 4) * 4u];\n                    const uint32_t d[4] = { w8.x, w8.y, w8.z, w8.w };\n', '                float wsr[8];\n                if constexpr (SB == 256u) {\n                    const uint32_t* scale = &s_ws[(wave * kFolds + f) * 16u + (lane >> 4) * 8u];\n#pragma unroll\n                    for (uint32_t t = 0; t < 8; ++t) wsr[t] = __uint_as_float(scale[t]);\n                } else {\n                    const uint4 w8 =\n                        *(const uint4*)&s_ws[(wave * kFolds + f) * 8u + (lane >> 4) * 4u];\n                    const uint32_t d[4] = { w8.x, w8.y, w8.z, w8.w };\n'),
        rep('rum15-kpar-fold', '        const uint4 q4 = *(const uint4*)(Sa + ((size_t)rt * ngrp + g) * 16u + acc_row(lane, 0));\n        const uint32_t qd[4] = { q4.x, q4.y, q4.z, q4.w };\n#pragma unroll\n        for (uint32_t j = 0; j < NT; ++j) {\n            const float as = xsr[j][g];\n#pragma unroll\n            for (uint32_t t = 0; t < 4; ++t) {\n                out[j][2 * t] = __builtin_fmaf(acc_i32(raw[j][2 * t]),\n                                               __uint_as_float(qd[t] << 16) * as, out[j][2 * t]);\n                out[j][2 * t + 1] = __builtin_fmaf(acc_i32(raw[j][2 * t + 1]),\n                                                   __uint_as_float(qd[t] & 0xFFFF0000u) * as,\n                                                   out[j][2 * t + 1]);\n            }\n        }\n', '        if constexpr (SB == 256u) {\n            const float* scale = (const float*)Sa + ((size_t)rt * ngrp + g) * 16u + acc_row(lane, 0);\n#pragma unroll\n            for (uint32_t j = 0; j < NT; ++j) {\n                const float as = xsr[j][g];\n#pragma unroll\n                for (uint32_t t = 0; t < 8; ++t)\n                    out[j][t] = __builtin_fmaf(acc_i32(raw[j][t]), scale[t] * as, out[j][t]);\n            }\n        } else {\n        const uint4 q4 = *(const uint4*)(Sa + ((size_t)rt * ngrp + g) * 16u + acc_row(lane, 0));\n        const uint32_t qd[4] = { q4.x, q4.y, q4.z, q4.w };\n#pragma unroll\n        for (uint32_t j = 0; j < NT; ++j) {\n            const float as = xsr[j][g];\n#pragma unroll\n            for (uint32_t t = 0; t < 4; ++t) {\n                out[j][2 * t] = __builtin_fmaf(acc_i32(raw[j][2 * t]),\n                                               __uint_as_float(qd[t] << 16) * as, out[j][2 * t]);\n                out[j][2 * t + 1] = __builtin_fmaf(acc_i32(raw[j][2 * t + 1]),\n                                                   __uint_as_float(qd[t] & 0xFFFF0000u) * as,\n                                                   out[j][2 * t + 1]);\n            }\n        }\n        }\n'),
    )),
    FilePatch(path='libr4d/r4d_gemm_8a8_prefill.h', language="none",
              description="RUM15 IQ8R F32 scale reads", edits=(
        rep('rum15-prefill-1', '        uint4 w8[!RB ? kPTW : 1u];\n', '        uint4 w8[!RB && SB != 256u ? kPTW : 1u];\n        float w32[!RB && SB == 256u ? kPTW * 8u : 1u];\n'),
        rep('rum15-prefill-2', '                if constexpr (ROWM) {\n                    /* Eight bf16 scales, one a row, packed as the tile-major uint4 the fold reads. */\n', '                if constexpr (SB == 256u) {\n                    const float* scale = (const float*)Sw + ((size_t)(wt0 + i) * nkb + kb) * 16u +\n                                         (lane >> 4) * 8u;\n#pragma unroll\n                    for (uint32_t t = 0; t < 8; ++t) w32[i * 8u + t] = scale[t];\n                } else if constexpr (ROWM) {\n                    /* Eight bf16 scales, one a row, packed as the tile-major uint4 the fold reads. */\n'),
        rep('rum15-prefill-3', '                float s[8];\n                const uint32_t d[4] = { w8[i].x, w8[i].y, w8[i].z, w8[i].w };\n#pragma unroll\n                for (uint32_t t = 0; t < 8; ++t)\n                    s[t] = as * bscale((uint16_t)(d[t / 2] >> (16 * (t % 2))));\n', '                float s[8];\n                if constexpr (SB == 256u) {\n#pragma unroll\n                    for (uint32_t t = 0; t < 8; ++t) s[t] = as * w32[i * 8u + t];\n                } else {\n                    const uint32_t d[4] = { w8[i].x, w8[i].y, w8[i].z, w8[i].w };\n#pragma unroll\n                    for (uint32_t t = 0; t < 8; ++t)\n                        s[t] = as * bscale((uint16_t)(d[t / 2] >> (16 * (t % 2))));\n                }\n'),
    )),
    FilePatch(path='libr4d/r4d_selftest.cpp', language="none",
              description='RUM15 selftest F32 IQ8R scale', edits=(
        rep('rum15-selftest-1', '}\n\n/* IQ8R: int8 codes rotated 128 wide under a u8 scale per (row, 256 of K) and a bf16 scale a row,\n * which the layout multiplies into one bf16 per (row, 256), against an int8\n * activation with one f32 scale per (token, 256). Four checks, each against an independent host\n * computation or the unfused pair:\n *   - had_quant_act_i8g at group 256 against the host rule (each 128 rotated by h_fwht, one amax\n', '}\n\n/* IQ8R: int8 codes rotated 128 wide under a u8 scale per (row, 256 of K) and a bf16 scale a row,\n * which the layout multiplies into one F32 per (row, 256), against an int8\n * activation with one f32 scale per (token, 256). Four checks, each against an independent host\n * computation or the unfused pair:\n *   - had_quant_act_i8g at group 256 against the host rule (each 128 rotated by h_fwht, one amax\n'),
        rep('rum15-selftest-2', '        /* The weight as libquant\'s rtn writes `codes=i8 group=256 scale=u8 scale2=bf16 block2=1x*\n         * transform=fwht128`: a row\'s bf16 second level is its largest group scale over 255, each\n         * group\'s u8 first level is relative to it, and the codes are chosen against their product.\n         * `eff` is the bf16 of that product, which the layout hands the kernels. */\n        Planes p;\n        rad_enc_clear(&p.enc);\n        rad_enc_copy_str(p.enc.scheme, "affine");\n', '        /* The weight as libquant\'s rtn writes `codes=i8 group=256 scale=u8 scale2=bf16 block2=1x*\n         * transform=fwht128`: a row\'s bf16 second level is its largest group scale over 255, each\n         * group\'s u8 first level is relative to it, and the codes are chosen against their product.\n         * `eff` retains the exact F32 product of the two source scales. */\n        Planes p;\n        rad_enc_clear(&p.enc);\n        rad_enc_copy_str(p.enc.scheme, "affine");\n'),
        rep('rum15-selftest-3', '            }\n            /* The rotation\'s 1/128 goes into the second level, exactly. */\n            rad_store_f32(p.data[2].data(), RAD_BF16, n, s2 / 128.0f);\n            for (int64_t g = 0; g < nkb; ++g) {\n                uint16_t h = 0;\n                rad_store_f32(&h, RAD_BF16, 0, (float)p.data[1][(size_t)(n * nkb + g)] * (s2 / 128.0f));\n                eff[(size_t)(n * nkb + g)] = rad_load_f32(&h, RAD_BF16, 0);\n            }\n        }\n        const std::vector<RadParam> lp = { PI("N", N), PI("K", K), PI("group", G), PS("dtype", "i8a8h") };\n        std::vector<uint8_t> wq, wsc;\n', '            }\n            /* The rotation\'s 1/128 goes into the second level, exactly. */\n            rad_store_f32(p.data[2].data(), RAD_BF16, n, s2 / 128.0f);\n            for (int64_t g = 0; g < nkb; ++g)\n                eff[(size_t)(n * nkb + g)] =\n                    (float)p.data[1][(size_t)(n * nkb + g)] * (s2 / 128.0f);\n        }\n        const std::vector<RadParam> lp = { PI("N", N), PI("K", K), PI("group", G), PS("dtype", "i8a8h") };\n        std::vector<uint8_t> wq, wsc;\n'),
        rep('rum15-selftest-4', '        }\n        std::vector<RadTensor> ts = {\n            T(d_q, RAD_I8, { M, K }), T(d_qs, RAD_F32, { M, nkb }), T(d_w, RAD_I8, { N, K }),\n            T(d_s, RAD_BF16, { N, nkb }), T(d_y, RAD_BF16, { M, N }), T(nullptr, RAD_F32, { 1 }),\n            T(nullptr, RAD_U8, { 1 }),\n        };\n        absent(ts[5]); absent(ts[6]);\n', '        }\n        std::vector<RadTensor> ts = {\n            T(d_q, RAD_I8, { M, K }), T(d_qs, RAD_F32, { M, nkb }), T(d_w, RAD_I8, { N, K }),\n            T(d_s, RAD_F32, { N, nkb }), T(d_y, RAD_BF16, { M, N }), T(nullptr, RAD_F32, { 1 }),\n            T(nullptr, RAD_U8, { 1 }),\n        };\n        absent(ts[5]); absent(ts[6]);\n'),
    )),
)
